// MCP Servers (migrated from .mcp.json with active ones only)
"mcp": {
  "Context7": {
    "enabled": true,
    "type": "local",
    "command": ["npx", "-y", "@upstash/context7-mcp"]
  },
  "gitmcp": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "-y", "mcp-remote", "https://gitmcp.io/docs"]
  },
  "apify": {
    "enabled": false,
    "type": "http",
    "url": "https://mcp.apify.com"
  },
  "playwright": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "-y", "@playwright/mcp@latest"]
  },
  "rag-browser": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "@apify/mcp-server-rag-web-browser"],
    "env": {
      "APIFY_TOKEN": "${APIFY_API_TOKEN_MCP}",
      "APIFY_META_ORIGIN": "STANDBY"
    }
  },
  "postgres-backend": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "@modelcontextprotocol/server-postgres", "postgresql://postgres:password@localhost:5432/myproject-c"]
  },
  "postgres-backend-remote": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "@modelcontextprotocol/server-postgres", "postgresql://postgres:password@myproject-c.companyone.example.com:5432/myproject-c"]
  },
  "chrome-mcp": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "node", "/Users/user/.local/share/mise/installs/node/24.4.1/lib/node_modules/mcp-chrome-bridge/dist/mcp/mcp-server-stdio.js"]
  },
  "time": {
    "enabled": false,
    "type": "local",
    "command": ["uvx", "mcp-server-time", "--local-timezone=Europe/Lisbon"]
  },
  "firecrawl": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "-y", "firecrawl-mcp"]
  },
  "tavily-mcp": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "-y", "tavily-mcp"]
  },
  "github": {
    "enabled": false,
    "type": "local",
    "command": ["docker", "run", "-i", "--rm", "-e", "GITHUB_PERSONAL_ACCESS_TOKEN", "-e", "GITHUB_DYNAMIC_TOOLSETS=1", "ghcr.io/github/github-mcp-server:latest"]
  },
  "octocode": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "octocode-mcp@latest"]
  },
  "exa": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "-y", "exa-mcp-server"]
  },
  "chroma": {
    "enabled": false,
    "type": "local",
    "command": ["uvx", "chroma-mcp", "--client-type", "persistent", "--data-dir", "${HOME}/claude-global-chroma"],
    "env": {
      "CHROMA_EMBEDDING_FUNCTION": "BAAI/bge-base-en-v1.5",
      "CHROMA_BATCH_SIZE": "128",
      "CHROMA_MAX_DOCUMENTS": "200000",
      "CHROMA_SIMILARITY_THRESHOLD": "0.73",
      "CHROMA_HNSW_M": "32",
      "CHROMA_HNSW_EF_CONSTRUCTION": "400",
      "CHROMA_CACHE_SIZE": "5000"
    }
  },
  "llms-txt-mcp": {
    "enabled": false,
    "type": "local",
    "command": ["uv", "run", "--directory", "${HOME}/Projects/llms-txt-mcp", "llms-txt-mcp", "--store-path", "${PWD}/tmp/mcp-data", "https://ai-sdk.dev/llms.txt", "https://nextjs.org/docs/llms.txt", "https://hono.dev/llms.txt", "https://orm.drizzle.team/llms-full.txt", "https://zod.dev/llms.txt"]
  },
  "x3k-mcp": {
    "enabled": false,
    "type": "http",
    "url": "http://localhost:4111/mcp"
  },
  "posthog": {
    "enabled": false,
    "type": "local",
    "command": ["npx", "-y", "mcp-remote@latest", "https://mcp.posthog.com/sse", "--header", "Authorization:${POSTHOG_AUTH_HEADER}"],
    "env": {
      "POSTHOG_AUTH_HEADER": "${POSTHOG_AUTH_HEADER}"
    }
  },
  "repomix": {
    "enabled": false,
    "type": "local",
    "command": ["repomix", "--mcp"],
    "env": {
      "WORKING_DIR": "${PWD}"
    }
  },
  "serena": {
    "enabled": false,
    "type": "local",
    "command": ["uvx", "--from", "git+https://github.com/oraios/serena", "serena", "start-mcp-server", "--enable-web-dashboard", "false", "--context", "ide-assistant", "--project", "/Users/user/Projects/myproject-c"]
  }
},
